mapper.select:
SELECT R.TRANSFORM_RESULT_ID, R.TRANSFORM_TASK_ID, T.RAW_DATA_ID, D.EXTERNAL_API_ID, A.API_NAME, V.TRANSFORM_RULE_ID, U.RULE_NAME, V.VERSION_NO, V.DATA_FORMAT, R.CREATED_AT FROM SCHED_TRANSFORM_RESULT R INNER JOIN SCHED_TRANSFORM_TASK T ON R.TRANSFORM_TASK_ID = T.TRANSFORM_TASK_ID INNER JOIN SCHED_COLLECT_RAW_DATA D ON T.RAW_DATA_ID = D.RAW_DATA_ID INNER JOIN SCHED_EXTERNAL_API A ON D.EXTERNAL_API_ID = A.EXTERNAL_API_ID INNER JOIN SCHED_TRANSFORM_RULE_VERSION V ON T.TRANSFORM_RULE_VERSION_ID = V.TRANSFORM_RULE_VERSION_ID INNER JOIN SCHED_TRANSFORM_RULE U ON V.TRANSFORM_RULE_ID = U.TRANSFORM_RULE_ID WHERE 1 = 1
AND D.EXTERNAL_API_ID = #{searchDto.externalApiId}
AND V.TRANSFORM_RULE_ID = #{searchDto.transformRuleId}
AND R.CREATED_AT >= #{startAt}
AND R.CREATED_AT < #{endAt}
ORDER BY R.TRANSFORM_RESULT_ID DESC OFFSET #{searchDto.offset} ROWS FETCH NEXT #{searchDto.size} ROWS ONLY

SELECT COUNT(*)
  FROM SCHED_TRANSFORM_RESULT R
 INNER JOIN SCHED_TRANSFORM_TASK T
    ON R.TRANSFORM_TASK_ID = T.TRANSFORM_TASK_ID
 INNER JOIN SCHED_COLLECT_RAW_DATA D
    ON T.RAW_DATA_ID = D.RAW_DATA_ID
 INNER JOIN SCHED_TRANSFORM_RULE_VERSION V
    ON T.TRANSFORM_RULE_VERSION_ID = V.TRANSFORM_RULE_VERSION_ID
 WHERE 1 = 1

   AND D.EXTERNAL_API_ID = #{searchDto.externalApiId}


   AND V.TRANSFORM_RULE_ID = #{searchDto.transformRuleId}


   AND R.CREATED_AT  >=  #{startAt}


   AND R.CREATED_AT  <  #{endAt}
